// Layered guard: validate in, filter out, gate money, log all (plain JS)
function guardrails() {
  return {
    checkInput: (text) => !/ignore|system:|disregard/i.test(text) || "injection-pattern",
    checkOutput: (text) => /guarantee(d)? refund/i.test(text) ? "forbidden-promise" : true,
    needsApproval: (action) => action.money || action.external,
    audit: [],
    log(entry) { this.audit.push({ ...entry, at: Date.now() }); },
  };
}
// Layers independent: input failures never reach output checks, but each
// enforced regardless of prompt compliance — enforcement, not encouragement.

